/* ---------------- APP ---------------- */
function App(){
  const [cart, setCart] = useState([]);
  const { menuData, featuredData, categoriesList } = useLiveMenu();
  const [cartOpen, setCartOpen] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [confirmedOrder, setConfirmedOrder] = useState(null);
  const [isAdminPath, setIsAdminPath] = useState(false);
  const [currentPage, setCurrentPage] = useState('home'); // 'home' | 'gallery'

  useEffect(()=>{
    ScrollTrigger.refresh();
    if (typeof window !== 'undefined') {
      const p = window.location.pathname.toLowerCase();
      const hash = window.location.hash.toLowerCase();
      if (p.includes('admin')) {
        setIsAdminPath(true);
      } else if (p.includes('gallery') || hash.includes('gallery-page') || hash === '#gallery') {
        setCurrentPage('gallery');
      }
    }
  },[]);

  if (isAdminPath) {
    return <AdminGatewayView />;
  }

  const addToCart = (item)=>{
    setCart(prev=>[...prev, item]);
    setCartOpen(true);
  };
  const removeFromCart = (idx)=>{
    setCart(prev=> prev.filter((_,i)=> i!==idx));
  };

  const navTo = (id)=>{
    if (id === 'gallery' || id === 'gallery-page') {
      setCurrentPage('gallery');
      window.scrollTo({top: 0, behavior: 'smooth'});
      return;
    }
    if (currentPage !== 'home') {
      setCurrentPage('home');
      setTimeout(() => {
        const el = document.getElementById(id);
        if(el) el.scrollIntoView({behavior:'smooth', block:'start'});
      }, 100);
      return;
    }
    const el = document.getElementById(id);
    if(el) el.scrollIntoView({behavior:'smooth', block:'start'});
  };

  const handleOrderPlaced = (order) => {
    setCart([]);
    setCheckoutOpen(false);
    setConfirmedOrder(order);
  };

  return (
    <React.Fragment>
      {currentPage === 'gallery' ? (
        <GalleryPage
          onBackToHome={() => {
            setCurrentPage('home');
            window.scrollTo({top: 0, behavior: 'smooth'});
          }}
          onAddToCart={addToCart}
          cartCount={cart.length}
          onOpenCart={() => setCartOpen(true)}
        />
      ) : (
        <React.Fragment>
          <Navbar onNav={navTo} cartCount={cart.length} onCart={()=>setCartOpen(true)} />
          <Hero onNav={navTo} />
          <Featured onAdd={addToCart} featuredData={featuredData} />
          <Process />
          <Offer onNav={navTo} />
          <Menu onAdd={addToCart} menuData={menuData} categoriesList={categoriesList} />
          <About />
          <Testimonials />
          <Newsletter />
          <Footer onNav={navTo} />
        </React.Fragment>
      )}

      <Cart
        items={cart}
        open={cartOpen}
        onClose={()=>setCartOpen(false)}
        onRemove={removeFromCart}
        onOpenCheckout={()=>setCheckoutOpen(true)}
      />

      <CheckoutModal
        open={checkoutOpen}
        items={cart}
        onClose={()=>setCheckoutOpen(false)}
        onOrderPlaced={handleOrderPlaced}
      />

      <OrderSuccessModal
        order={confirmedOrder}
        onClose={()=>setConfirmedOrder(null)}
      />
    </React.Fragment>
  );
}

export default App;
